V_BI_WECOM_USER_DEPT.ddl:
CREATE OR REPLACE FORCE VIEW "HIS"."V_BI_WECOM_USER_DEPT" ("WECOM_USER_ID", "USER_NAME", "DEPT_CODE", "DEPT_NAME") AS 
select a.emp_no WECOM_USER_ID, a.name user_name ,a.dept_code  , b.dept_name from  STAFF_DICT a left join dept_dict b on a.dept_code=b.dept_code where a.STATUS='1'
